From 266adface589ca9333fed32e5e26d852ff293e23 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:03:28 +0100
Subject: [PATCH] wallpapers/image: add a Previous Wallpaper Image action to
 slideshows

Slideshow wallpapers could only move forward from the desktop context
menu, so a wallpaper that had just been replaced could not be brought
back. Add a matching action and global shortcut that go back one image.

BUG: 497537
---
 .../image/imagepackage/contents/ui/main.qml   |  2 +-
 wallpapers/image/plugin/imagebackend.cpp      | 39 +++++++++++++++++++
 wallpapers/image/plugin/imagebackend.h        |  5 +++
 3 files changed, 45 insertions(+), 1 deletion(-)

diff --git a/wallpapers/image/imagepackage/contents/ui/main.qml b/wallpapers/image/imagepackage/contents/ui/main.qml
index 14aac831f8..601a413bc6 100644
--- a/wallpapers/image/imagepackage/contents/ui/main.qml
+++ b/wallpapers/image/imagepackage/contents/ui/main.qml
@@ -30,7 +30,7 @@ WallpaperItem {
         root.configuration.writeConfig();
     }

-    contextualActions: root.pluginName === "org.kde.slideshow" ? [openWallpaperAction, imageWallpaper.nextSlideAction] : []
+    contextualActions: root.pluginName === "org.kde.slideshow" ? [openWallpaperAction, imageWallpaper.previousSlideAction, imageWallpaper.nextSlideAction] : []

     PlasmaCore.Action {
         id: openWallpaperAction
diff --git a/wallpapers/image/plugin/imagebackend.cpp b/wallpapers/image/plugin/imagebackend.cpp
index d4413791b1..00198ab5e4 100644
--- a/wallpapers/image/plugin/imagebackend.cpp
+++ b/wallpapers/image/plugin/imagebackend.cpp
@@ -40,6 +40,8 @@ ImageBackend::ImageBackend(QObject *parent)
     : QObject(parent)
     , m_targetSize(qGuiApp->primaryScreen()->size() * qGuiApp->primaryScreen()->devicePixelRatio())
     , m_nextSlideAction(new QAction(QIcon::fromTheme(QStringLiteral("user-desktop")), i18nd("plasma_wallpaper_org.kde.image", "Next Wallpaper Image"), this))
+    , m_previousSlideAction(
+          new QAction(QIcon::fromTheme(QStringLiteral("user-desktop")), i18nd("plasma_wallpaper_org.kde.image", "Previous Wallpaper Image"), this))
 {
     const QString slideActionId = QStringLiteral("Slideshow Wallpaper Next Image");
     m_nextSlideAction->setObjectName(slideActionId);
@@ -49,6 +51,14 @@ ImageBackend::ImageBackend(QObject *parent)
     m_nextSlideAction->setShortcut(KGlobalAccel::self()->globalShortcut(QStringLiteral("plasmashell"), slideActionId).value(0));
     connect(m_nextSlideAction, &QAction::triggered, this, &ImageBackend::nextSlide);

+    const QString previousSlideActionId = QStringLiteral("Slideshow Wallpaper Previous Image");
+    m_previousSlideAction->setObjectName(previousSlideActionId);
+    m_previousSlideAction->setProperty("componentName", QStringLiteral("plasmashell"));
+    m_previousSlideAction->setProperty("componentDisplayName", QStringLiteral("plasmashell"));
+    KGlobalAccel::self()->setGlobalShortcut(m_previousSlideAction, QKeySequence());
+    m_previousSlideAction->setShortcut(KGlobalAccel::self()->globalShortcut(QStringLiteral("plasmashell"), previousSlideActionId).value(0));
+    connect(m_previousSlideAction, &QAction::triggered, this, &ImageBackend::previousSlide);
+
     m_timer.setSingleShot(true);
     m_timer.setTimerType(Qt::PreciseTimer);
     connect(&m_timer, &QTimer::timeout, this, &ImageBackend::nextSlide);
@@ -546,7 +556,31 @@ void ImageBackend::nextSlide()
     }

     saveCurrentWallpaper();
+    restartSlideTimer();
+}
+
+void ImageBackend::previousSlide()
+{
+    const int rowCount = m_slideFilterModel->rowCount();

+    if (!m_ready || m_usedInConfig || rowCount == 0) {
+        return;
+    }
+    if (m_currentSlide <= 0 || m_currentSlide >= rowCount) {
+        m_currentSlide = rowCount - 1;
+    } else {
+        m_currentSlide -= 1;
+    }
+    const QModelIndex index = m_slideFilterModel->index(m_currentSlide, 0);
+    m_image = makeWallpaperUrl(index.data(ImageRoles::SourceRole).toUrl(), index.data(ImageRoles::SelectorsRole).toStringList());
+    Q_EMIT imageChanged();
+
+    saveCurrentWallpaper();
+    restartSlideTimer();
+}
+
+void ImageBackend::restartSlideTimer()
+{
     if (m_delay > 0) {
         // Synchronize wallpaper transitions across desktops on all screens and activities
         // by updating the wallpaper in strict time intervals since UNIX epoch, defined by `m_delay`.
@@ -654,3 +688,8 @@ QAction *ImageBackend::nextSlideAction() const
 {
     return m_nextSlideAction;
 }
+
+QAction *ImageBackend::previousSlideAction() const
+{
+    return m_previousSlideAction;
+}
diff --git a/wallpapers/image/plugin/imagebackend.h b/wallpapers/image/plugin/imagebackend.h
index 9416629f85..02ec39372b 100644
--- a/wallpapers/image/plugin/imagebackend.h
+++ b/wallpapers/image/plugin/imagebackend.h
@@ -94,6 +94,7 @@ class ImageBackend : public QObject, public QQmlParserStatus
     Q_PROPERTY(bool loading READ loading NOTIFY loadingChanged)

     Q_PROPERTY(QAction *nextSlideAction READ nextSlideAction CONSTANT)
+    Q_PROPERTY(QAction *previousSlideAction READ previousSlideAction CONSTANT)

 public:
     enum RenderingMode {
@@ -162,9 +163,11 @@ public:
     bool loading() const;

     QAction *nextSlideAction() const;
+    QAction *previousSlideAction() const;

 public Q_SLOTS:
     void nextSlide();
+    void previousSlide();
     void slotSlideModelDataChanged(const QModelIndex &topLeft, const QModelIndex &bottomRight, const QList<int> &roles);

 Q_SIGNALS:
@@ -194,6 +197,7 @@ private:
     void ensureSlideshowModel();

     void saveCurrentWallpaper();
+    void restartSlideTimer();

     bool m_ready = false;
     int m_delay = 10;
@@ -223,4 +227,5 @@ private:
     SlideFilterModel *m_slideFilterModel = nullptr;

     QAction *m_nextSlideAction;
+    QAction *m_previousSlideAction;
 };
-- 
